def slice_normal(self):
    """Return unit normal to the planes in the reconstructed frame order

    ``Wrapper.slice_normal`` derives the normal from the image orientation
    cross product.  Multi-frame objects do not require the frames to be
    stored in the order implied by the Dimension Index Values, so the sign
    has to be checked against the actual Plane Position values of the
    frames that will be adjacent in the reconstructed array.
    """
    base_normal = super().slice_normal
    if base_normal is None:
        return None
    try:
        self.image_shape
        first = self.frames[self._frame_order[0]]
        second = self.frames[self._frame_order[1]]
    except (WrapperError, AttributeError, IndexError, TypeError, AssertionError):
        return base_normal
    p0 = self._frame_position(first)
    p1 = self._frame_position(second)
    if p0 is None or p1 is None:
        return base_normal
    step = p1 - p0
    if not np.any(step):
        return base_normal
    # If the sorted frames move in the opposite direction to the
    # orientation-derived normal, flip the normal to match the data.
    if np.dot(step, base_normal) < 0:
        return -base_normal
    return base_normal

